'use strict';
const researchDeliveryView=overview;
let deskView=new URL(location.href).searchParams.has('case')?'delivery':'data',deskSearch='',deskCategory='all',deskRequested=false;
labels.overview='数据总览';
const deskNav=document.querySelector('[data-nav="overview"]');
if(deskNav){deskNav.setAttribute('aria-label','数据总览');deskNav.querySelector('.nav-full').textContent='数据总览';deskNav.querySelector('.nav-short').textContent='总览';}
function deskHasPrice(r){return [r.raw_price,r.normalized_price,...Object.values(r.raw_prices||{})].some(v=>v!==null&&v!==undefined&&String(v).trim()!==''&&Number.isFinite(Number(v)));}
function deskMetrics(rows){const hosts=new Set();for(const r of rows){try{const u=new URL(r.source_url);if(/^https?:$/.test(u.protocol))hosts.add(u.hostname.replace(/^www\./,''));}catch{}}return {count:rows.length,priced:rows.filter(deskHasPrice).length,sites:hosts.size,linked:rows.filter(r=>r.duplicate_of).length,barcode:rows.filter(r=>r.barcode&&r.barcode_format_valid).length};}
function deskPrice(r){if(r.origin==='legacy'){const p=r.raw_prices||{};return escapeHtml([p['批发价低'],p['批发价高'],p['零售价'],p['促销低价']].find(v=>v!=null&&String(v).trim()!=='')??'—')+'<small>历史原值 · 单位待核</small>';}return r.raw_price!=null?escapeHtml(fmt(r.raw_price))+'<small>'+escapeHtml(r.raw_unit||'原始单位待核')+'</small>':r.normalized_price!=null?escapeHtml(fmt(r.normalized_price))+'<small>'+escapeHtml(r.normalized_unit||'单位待核')+'</small>':'—<small>非价格资料</small>';}
function deskDate(r){for(const value of [r.collected_at,r.collection_date,r.source_date]){if(/^\d{4}-\d{2}-\d{2}/.test(value||''))return value;}return ''; }
function deskRows(){return records.filter(r=>(deskCategory==='all'||group(r)===deskCategory)&&[r.sku,r.spec,r.supplier,r.source_title,r.barcode].join(' ').toLowerCase().includes(deskSearch.trim().toLowerCase())).sort((a,b)=>Number(deskHasPrice(b))-Number(deskHasPrice(a))||deskDate(b).localeCompare(deskDate(a)));}
function deskTable(){const rows=deskRows();return '<div class="desk-table-top"><span>'+rows.length.toLocaleString()+' 条匹配 · 展示前 12 条</span><a href="#database" data-desk-library>完整检索 ↗</a></div><div class="desk-table-scroll" tabindex="0" aria-label="商品观察表，可横向滚动"><table class="desk-table"><thead><tr><th>商品 / 包装规格</th><th>品类</th><th>原始价格</th><th>供应商 / 来源</th><th>来源日期</th><th>证据状态</th></tr></thead><tbody>'+rows.slice(0,12).map(r=>'<tr data-key="'+escapeHtml(keyOf(r))+'" tabindex="0" class="product-row"><td><b>'+escapeHtml(r.sku||r.title)+'</b><small>'+escapeHtml(r.spec)+'</small></td><td>'+escapeHtml(group(r))+'</td><td class="desk-price">'+deskPrice(r)+'</td><td>'+escapeHtml(r.supplier||r.source_title||'待核')+'</td><td>'+escapeHtml(r.source_date||'未明示')+'<small>采集 '+escapeHtml(r.collected_at||r.collection_date||'未明示')+'</small></td><td><span class="desk-tag">'+(r.duplicate_of?'重访关联':r.origin==='legacy'?'历史原值':r.candidate_for_comparison?'复核候选':'研究参考')+'</span></td></tr>').join('')+'</tbody></table>'+(rows.length?'':'<p class="desk-empty">没有匹配记录，试试其他商品或品类。</p>')+'</div><p class="desk-footnote">价格按原单位展示，异地挂牌与历史原值均需核税运、有效期和成都到店条件。</p>';}
function deskCoverage(){const rows=coverage(),max=rows[0]?.all||1;return '<div class="desk-chart-scale"><span>观察记录数</span><span>0 — '+max+'</span></div><div class="desk-category-chart">'+rows.map(c=>'<button data-desk-category="'+escapeHtml(c.name)+'"><span>'+escapeHtml(c.name)+'</span><i><em style="width:'+(100*c.all/max).toFixed(1)+'%"></em></i><b>'+c.all+'</b></button>').join('')+'</div><p class="desk-footnote">记录覆盖量，非销量或消费热度。点击品类联动上方商品表。</p>';}
function deskAgent(){return '<section class="desk-panel desk-agent" id="desk-ai"><div class="desk-panel-head"><h2>AI 复核与下一步</h2><span class="desk-tag">已发布研究</span></div>'+availableMissions().map(m=>'<button class="desk-mission" data-desk-mission="'+escapeHtml(m.id)+'"><span>'+escapeHtml(m.kind)+' <i>'+escapeHtml(safeMissionState(m))+'</i></span><strong>'+escapeHtml(m.title)+'</strong><p>'+escapeHtml(missionIntegrity(m).valid?m.short:'原判断待复核，请先检查引用与时效。')+'</p><small>'+((m.record_ids||[]).length+(m.signal_ids||[]).length)+' 条引用 · '+escapeHtml(m.reviewed_at)+' 复核 <b>查看过程 ↗</b></small></button>').join('')+(!availableMissions().length?'<p class="desk-footnote">复核任务载入中，可先浏览数据。</p>':'')+'</section>';}
function deskMonitor(){const h=monitorHealth(),runs=watchRuns().slice(-8);return '<section class="desk-panel"><div class="desk-panel-head"><h2>持续采集</h2><a href="#watch">运行详情 ↗</a></div><div class="desk-monitor-score"><strong>'+h.good+'<small> / '+h.total+'</small></strong><span>本轮来源成功<br>'+escapeHtml(shortDate(watchData?.generated_at))+'</span></div><div class="desk-runs">'+runs.map(r=>'<span class="'+(r.failure_count?'partial':'good')+'" title="'+escapeHtml(shortDate(r.checked_at)+' · '+r.success_count+'成功 / '+r.failure_count+'失败')+'"></span>').join('')+'</div><p class="desk-footnote">最近 '+runs.length+' 次实际运行 · 绿色全部成功 / 土色部分失败</p>'+sourceList().map(s=>'<div class="desk-source"><span>'+escapeHtml(s.name)+'</span><b>'+ (sourceIsGood(s)?'已检查':'未成功')+'</b></div>').join('')+'<p class="desk-footnote">'+changesList().length+' 条累计正文变化；首次基线不算新动态。固定检查每 6 小时计划运行，AI 研究每日计划复核。</p></section>';}
function renderDesk(){const m=deskMetrics(records),cats=coverage();main.className='data-desk';main.innerHTML='<div class="desk-heading"><div><span>EVERY MART / RETAIL INTELLIGENCE</span><h1>集刻经营数据总览</h1><p>商品与价格、品类、竞对、供货渠道，持续积累到同一个研究底座。</p></div><a class="btn" href="#database">进入完整商品库 ↗</a></div><div class="desk-metrics">'+[[m.count.toLocaleString(),'研究观察','含历史与同商品多源记录'],[m.priced.toLocaleString(),'含价格观察','字段有数值，非有效报价数'],[cats.length,'研究分类','品类及渠道行业资料'],[m.sites,'公开来源站点','按 URL 主机名去重'],[reports.length,'完整研究报告','保留来源与数据缺口'],[m.linked,'已标注重复关联','仅已建立的明确关系']].map(x=>'<div><strong>'+x[0]+'</strong><b>'+x[1]+'</b><small>'+x[2]+'</small></div>').join('')+'</div><div class="desk-links">'+[['database','商品价格库'],['categories','品类配置'],['competitors','五大竞对'],['suppliers','供应渠道'],['reports','研究档案'],['store','门店实采']].map(x=>'<a href="#'+x[0]+'">'+x[1]+' ↗</a>').join('')+'</div><button class="desk-ai-shortcut" data-desk-ai><b>AI 复核</b><span>'+availableMissions().length+' 项已发布研究 · 查看判断、证据与下一步</span><i>↓</i></button><div class="desk-grid"><div class="desk-primary"><section class="desk-panel"><div class="desk-panel-head"><h2>商品与价格观察</h2><a href="#products">去核到店成本 ↗</a></div><div class="desk-filters"><input id="desk-search" aria-label="总览搜索商品" placeholder="搜索商品、条码、供应商…" value="'+escapeHtml(deskSearch)+'"><select id="desk-category" aria-label="总览品类"><option value="all">全部研究分类</option>'+cats.map(c=>'<option '+(deskCategory===c.name?'selected':'')+'>'+escapeHtml(c.name)+'</option>').join('')+'</select></div><div id="desk-results">'+deskTable()+'</div></section><div class="desk-bottom"><section class="desk-panel"><div class="desk-panel-head"><h2>全品类覆盖分布</h2><a href="#categories">配置 ↗</a></div>'+deskCoverage()+'</section><section class="desk-panel"><div class="desk-panel-head"><h2>竞对研究矩阵</h2><a href="#competitors">档案 ↗</a></div>'+competitorsData.map(c=>'<a class="desk-competitor" href="#competitors"><b>'+escapeHtml(c[0])+'</b><span>'+escapeHtml(c[1])+'</span><small>'+c[4].map(n=>'引 '+n).join(' / ')+' ↗</small></a>').join('')+'<p class="desk-footnote">品牌研究重点，当前门店实况需同商圈核验。</p></section></div><section class="desk-panel desk-suppliers"><div class="desk-panel-head"><h2>成都相关供货渠道</h2><a href="#suppliers">全部线索 ↗</a></div>'+supply.slice(0,4).map(c=>'<a href="#suppliers"><span>'+escapeHtml(c[0])+'</span><b>'+escapeHtml(c[1])+'</b><small>待核：'+escapeHtml(c[3])+'</small></a>').join('')+'</section></div><aside class="desk-rail">'+deskAgent()+deskMonitor()+'<section class="desk-panel"><div class="desk-panel-head"><h2>证据加工成果</h2></div>'+[['条码格式已校验',m.barcode+' 条记录'],['保留历史原始价格',countScope('legacy')+' 条记录'],['同源重访不重复报新','保留关联与采集日期'],['证据变更自动降级','已接入首页任务校验']].map(x=>'<div class="desk-source"><span>'+x[0]+'</span><b>'+x[1]+'</b></div>').join('')+'<p class="desk-footnote">AI 的价值体现在持续研究、条件核对与历史关联；不是页面实时推理。记录数不等于独立 SKU。</p></section></aside></div>';
 document.getElementById('desk-search').oninput=e=>{deskSearch=e.target.value;document.getElementById('desk-results').innerHTML=deskTable()};document.getElementById('desk-category').onchange=e=>{deskCategory=e.target.value;document.getElementById('desk-results').innerHTML=deskTable()};}
overview=function(){if(deskView==='delivery'){researchDeliveryView();main.insertAdjacentHTML('afterbegin','<button class="btn desk-back" data-desk-home>← 返回数据总览</button>');return;}if(!libraryReady){main.className='data-desk';main.innerHTML='<div class="desk-heading"><div><h1>集刻经营数据总览</h1><p>'+(libraryError?'完整数据暂未载入，请重试。':'正在汇集商品价格、品类覆盖、竞对和供应渠道…')+'</p></div></div><button class="btn" data-desk-retry>重新载入数据</button><a class="btn" href="#products">先使用核价工具 ↗</a>';if(!deskRequested&&!libraryError){deskRequested=true;ensureLibrary().then(()=>{if((location.hash.slice(1)||'overview')==='overview'&&deskView==='data')overview()}).catch(()=>{if((location.hash.slice(1)||'overview')==='overview')overview()}).finally(()=>deskRequested=false);}return;}renderDesk();};
document.addEventListener('click',e=>{if(e.target.closest('[data-desk-ai]')){document.getElementById('desk-ai')?.scrollIntoView({block:'start'});return;}const mission=e.target.closest('[data-desk-mission]');if(mission){deskView='delivery';focusMission(mission.dataset.deskMission);window.scrollTo({top:0,behavior:'instant'});return;}if(e.target.closest('[data-desk-home]')||e.target.closest('[data-nav="overview"]')){deskView='data';const u=new URL(location.href);u.searchParams.delete('case');history.replaceState(null,'',u);overview();window.scrollTo({top:0,behavior:'instant'});return;}const categoryButton=e.target.closest('[data-desk-category]');if(categoryButton){deskCategory=categoryButton.dataset.deskCategory;document.getElementById('desk-category').value=deskCategory;document.getElementById('desk-results').innerHTML=deskTable();document.getElementById('desk-search').scrollIntoView({block:'center'});return;}if(e.target.closest('[data-desk-library]')){query=deskSearch;category=deskCategory;scope=priceType='all';page=1;}if(e.target.closest('[data-desk-retry]')){libraryError=false;deskRequested=false;overview();}});
